'use strict';
const fs=require('fs'),path=require('path'),assert=require('assert');
const Yahoo=require('../js/yahoo-season-v1.js'),Sync=require('../js/yahoo-sync-v1.js'),Season=require('../js/season-command-center-v1.js');
const fixture=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/yahoo/league_bundle_2026.json'),'utf8'));
const realFixture=JSON.parse(fs.readFileSync(path.join(__dirname,'fixtures/yahoo/real_nested_season_2026_sanitized.json'),'utf8'));
const tests=[],metrics={};function test(name,fn){tests.push({name,fn});}
const utf8=value=>Buffer.byteLength(JSON.stringify(value),'utf8');
function memoryStorage(){const map=new Map();let max=Infinity,writes=0;return{map,getItem:key=>map.has(key)?map.get(key):null,setItem(key,value){writes++;if(Buffer.byteLength(String(value),'utf8')>max){const error=new Error('quota');error.name='QuotaExceededError';throw error;}map.set(key,String(value));},removeItem:key=>map.delete(key),setLimit:value=>{max=value;},writes:()=>writes};}
function snapshot(label,index,{padding=0}={}){const fetchedAt=`2026-09-${String(index+1).padStart(2,'0')}T12:00:00.000Z`,userKey=`league-${label}.t.2`,opponentKey=`league-${label}.t.7`,teams=Array.from({length:10},(_,offset)=>({teamKey:`league-${label}.t.${offset+1}`,name:`Team ${offset+1}`,isUser:offset===1,roster:Array.from({length:16},(_row,slot)=>({yahooPlayerId:`${label}-${offset}-${slot}`,name:`Player ${offset}-${slot}`,position:slot%3?'WR':'RB',rosterSlot:slot<9?'FLEX':'BN',identity:{canonicalPlayerId:`p-${label}-${offset}-${slot}`}}))}));return{schema:Yahoo.SCHEMA,profileId:label,provider:'Yahoo',fetchedAt,league:{leagueKey:`league-${label}`,gameCode:'nfl',season:2026,currentWeek:2},teams,userTeamKey:userKey,availablePlayers:Array.from({length:40},(_row,slot)=>({yahooPlayerId:`fa-${label}-${slot}`,name:`Available Player ${slot}`,position:'WR'})),transactions:[{transactionKey:`tr-${index}`}],standings:[{teamKey:userKey,rank:9,wins:0,losses:1,ties:0,pointsFor:116.58,pointsAgainst:188.83,playoffSeed:9}],matchups:{week:2,matchups:[{matchupId:`m-${index}`,status:'midevent',teamKeys:[userKey,opponentKey],teams:[{teamKey:userKey,actualPoints:0,projectedPoints:144.63,winProbability:.23},{teamKey:opponentKey,actualPoints:91.9,projectedPoints:139.02,winProbability:.77}]}]},legacyAuditBlob:padding?'x'.repeat(padding):undefined};}
function realisticSnapshot(){const userKey='470.l.164770.t.2',standings=Yahoo.normalizeStandings(realFixture.standings),matchups=Yahoo.normalizeMatchups(realFixture.matchups),teams=standings.map((standing,index)=>({teamKey:standing.teamKey,name:index===1?'Test Manager':'Sanitized Team '+(index+1),isUser:standing.teamKey===userKey,managerName:standing.teamKey===userKey?'Test Manager':null,roster:Array.from({length:16},(_row,slot)=>({yahooPlayerId:`roster-${index}-${slot}`,name:`Roster Player ${index}-${slot}`,position:slot%4===0?'QB':slot%3===0?'RB':'WR',rosterSlot:slot<9?'FLEX':'BN',identity:{canonicalPlayerId:`canonical-roster-${index}-${slot}`,status:'MATCHED'}}))}));return{schema:Yahoo.SCHEMA,profileId:'realistic',provider:'Yahoo',readOnly:true,fetchedAt:'2026-09-18T12:00:00.000Z',league:{leagueKey:'470.l.164770',name:'Sanitized Regression League',gameCode:'nfl',season:2026,teamCount:10,currentWeek:2},settings:{teamCount:10,scoringType:'half-ppr',rosterSlots:['QB','RB','RB','WR','WR','TE','FLEX','K','DST','BN','BN','BN','BN','BN','BN','IR']},teams,userTeamKey:userKey,currentRoster:{teamKey:userKey,roster:teams.find(team=>team.teamKey===userKey).roster},availablePlayers:Array.from({length:1400},(_row,index)=>({yahooPlayerId:`available-${index}`,name:`Available Player ${index} ${'x'.repeat(40)}`,position:index%2?'WR':'RB',ownership:index%3?'FA':'W',identity:{canonicalPlayerId:`canonical-available-${index}`,status:'MATCHED'}})),transactions:[{transactionKey:'470.l.164770.tr.1',type:'add',status:'successful',timestamp:1787510000,players:[]}],standings,matchups,identitySummary:{total:1560,MATCHED:1560,ALIAS_MATCH:0,AMBIGUOUS:0,UNRESOLVED:0},ownership:{ownership:{},conflicts:[],valid:true},settingsReconciliation:{status:'MATCH'},sourceMetadata:{responseFormat:'json',availablePlayerRows:1400},datasets:{},subsystemErrors:{},draftLinkage:{status:'NOT_LINKED'},seasonMode:{status:'ACTIVE_DATA',fantasyWeek:2}};}

test('legacy full-snapshot history migrates without changing the authoritative snapshot',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),current=snapshot('legacy',2,{padding:640000}),historical=snapshot('legacy',1,{padding:640000}),state={schema:Yahoo.SCHEMA,profileId:'legacy',mapping:{leagueKey:'league-legacy',explicitlyConfirmed:true},sync:{status:'CURRENT',lastSuccessfulSyncAt:current.fetchedAt},snapshot:current,snapshots:[historical,current]},before=utf8(state),currentBytes=JSON.stringify(current);storage.setItem(store.key('legacy'),JSON.stringify(state));const migrated=store.read('legacy'),after=utf8(migrated);metrics.legacyBeforeBytes=before;metrics.legacyAfterBytes=after;assert.strictEqual(JSON.stringify(migrated.snapshot),currentBytes);assert.strictEqual(migrated.snapshots,undefined);assert.strictEqual(migrated.checkpoints.length,1);assert.strictEqual(migrated.mapping.leagueKey,'league-legacy');assert.strictEqual(migrated.sync.lastSuccessfulSyncAt,current.fetchedAt);assert(after<before*.55);});
test('compact checkpoints exclude full rosters pools ownership and raw structures',()=>{const point=Yahoo.checkpointFromSnapshot(snapshot('compact',1));for(const forbidden of ['availablePlayers','ownership','teams','transactions','raw','legacyAuditBlob'])assert(!Object.hasOwn(point,forbidden));assert.strictEqual(point.standing.wins,0);assert.strictEqual(point.matchup.userActualPoints,0);});
test('legacy direct-array matchups retain compact historical matchup values',()=>{const legacy=snapshot('legacy-array',1),rows=legacy.matchups.matchups;legacy.matchups=rows;const point=Yahoo.checkpointFromSnapshot(legacy);assert.strictEqual(point.week,2);assert.strictEqual(point.matchup.userActualPoints,0);assert.strictEqual(point.matchup.opponentActualPoints,91.9);});
test('sanitized realistic snapshot survives compact persistence with every Season field intact',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),current=realisticSnapshot(),historical={...JSON.parse(JSON.stringify(current)),fetchedAt:'2026-09-17T12:00:00.000Z'},legacy={schema:Yahoo.SCHEMA,profileId:'realistic',mapping:{leagueKey:'470.l.164770',explicitlyConfirmed:true},sync:{status:'CURRENT',lastSuccessfulSyncAt:current.fetchedAt},snapshot:current,snapshots:[historical,current]},before=utf8(legacy);store.write('realistic',legacy);const saved=store.read('realistic'),after=storeSize(storage,store.key('realistic')),model=Season.buildModel({state:saved,profile:{id:'realistic'}}),serialized=storage.getItem(store.key('realistic'));metrics.realisticPreFixBytes=before;metrics.realisticAfterBytes=after;metrics.realisticCurrentSnapshotBytes=utf8(saved.snapshot);assert(after<before*.55);assert.strictEqual(saved.snapshots,undefined);assert.strictEqual(saved.checkpoints.length,1);assert(!serialized.includes('"raw"'));assert.strictEqual(saved.snapshot.teams.length,10);assert.strictEqual(saved.snapshot.availablePlayers.length,1400);assert.strictEqual(saved.snapshot.transactions.length,1);assert.strictEqual(model.userTeam.teamKey,'470.l.164770.t.2');assert.strictEqual(model.standing.rank,9);assert.strictEqual(model.standing.wins,0);assert.strictEqual(model.standing.losses,1);assert.strictEqual(model.standing.pointsFor,116.58);assert.strictEqual(model.standing.pointsAgainst,188.83);assert.strictEqual(model.opponent.teamKey,'470.l.164770.t.7');assert.deepStrictEqual(model.userMatchupSide,{teamKey:'470.l.164770.t.2',actualPoints:0,weeklyProjectedPoints:144.54,projectedPoints:144.54,currentProjectedFinal:null,winProbability:0.22});assert.deepStrictEqual(model.opponentMatchupSide,{teamKey:'470.l.164770.t.7',actualPoints:91.9,weeklyProjectedPoints:139.57,projectedPoints:139.57,currentProjectedFinal:null,winProbability:0.78});});
test('persistence boundary supports read write update remove and estimates',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),state={mapping:{provider:'Yahoo'},snapshot:snapshot('api',1),checkpoints:[]};store.write('api',state);store.update('api',current=>({...current,sync:{status:'CURRENT'}}));assert.strictEqual(store.read('api').sync.status,'CURRENT');const estimate=store.estimate('api');assert.strictEqual(estimate.backend,'localStorage');assert(estimate.snapshotBytes>0&&estimate.totalBytes>=estimate.snapshotBytes);store.remove('api');assert.strictEqual(store.read('api'),null);});
test('legacy migration and compaction are isolated by profile',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),a=snapshot('a',2),b=snapshot('b',2),legacyA={schema:Yahoo.SCHEMA,profileId:'a',mapping:{leagueKey:'league-a'},snapshot:a,snapshots:[snapshot('a',1),a]},stateB={schema:Yahoo.SCHEMA,profileId:'b',mapping:{leagueKey:'league-b'},snapshot:b,checkpoints:[Yahoo.checkpointFromSnapshot(b)]};storage.setItem(store.key('a'),JSON.stringify(legacyA));storage.setItem(store.key('b'),JSON.stringify(stateB));const beforeB=storage.getItem(store.key('b')),readA=store.read('a');assert.strictEqual(readA.snapshots,undefined);assert.strictEqual(storage.getItem(store.key('b')),beforeB);assert.strictEqual(store.read('b').mapping.leagueKey,'league-b');});
test('quota fallback reduces optional checkpoints before sacrificing current snapshot',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),current=snapshot('quota',2,{padding:90000}),checkpoints=Array.from({length:30},(_,index)=>Yahoo.checkpointFromSnapshot(snapshot('quota',index))),desired=Yahoo.compactSeasonState({schema:Yahoo.SCHEMA,profileId:'quota',snapshot:current,checkpoints}),reduced={...desired,checkpoints:desired.checkpoints.slice(-8)},limit=Math.floor((utf8(desired)+utf8(reduced))/2);storage.setItem('unrelated','keep-me');storage.setLimit(limit);const saved=store.write('quota',desired);assert(saved.checkpoints.length<=8);assert.strictEqual(JSON.stringify(saved.snapshot),JSON.stringify(current));assert.strictEqual(storage.getItem('unrelated'),'keep-me');assert(storage.writes()>=3);});
test('exhausted quota preserves the previous successful Yahoo state and unrelated keys',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),previous={schema:Yahoo.SCHEMA,profileId:'blocked',snapshot:snapshot('blocked',1),mapping:{leagueKey:'league-blocked'},checkpoints:[]};store.write('blocked',previous);storage.setItem('unrelated','keep-me');const before=storage.getItem(store.key('blocked'));storage.setLimit(100);assert.throws(()=>store.write('blocked',{...previous,snapshot:snapshot('blocked',2,{padding:20000})}),error=>error.code==='YAHOO_SEASON_STORAGE_QUOTA');assert.strictEqual(storage.getItem(store.key('blocked')),before);assert.strictEqual(storage.getItem('unrelated'),'keep-me');});
test('quota recovery never deletes or rewrites another league profile',()=>{const storage=memoryStorage(),store=Yahoo.createStore(storage),other={schema:Yahoo.SCHEMA,profileId:'other',snapshot:snapshot('other',1),mapping:{leagueKey:'league-other'},checkpoints:[]};store.write('other',other);const before=storage.getItem(store.key('other'));storage.setLimit(100);assert.throws(()=>store.write('target',{snapshot:snapshot('target',1,{padding:20000})}),/quota/i);assert.strictEqual(storage.getItem(store.key('other')),before);});
test('normalized Yahoo players and leagues no longer retain source payload copies',()=>{const player=Yahoo.normalizeYahooPlayer({player_key:'470.p.1',name:{full:'Test Player'},display_position:'WR',nested:'unused'}),league=Yahoo.normalizeLeagueList({leagues:[{leagueKey:'league',name:'League',season:2026,gameCode:'nfl',privatePayload:'unused'}]})[0];assert(!Object.hasOwn(player,'raw'));assert(!Object.hasOwn(league,'raw'));assert(!JSON.stringify(player).includes('unused'));assert(!JSON.stringify(league).includes('privatePayload'));});
test('Season persistence modules depend on an injected backend rather than window localStorage',()=>{const seasonSource=fs.readFileSync(path.join(__dirname,'../js/yahoo-season-v1.js'),'utf8'),syncSource=fs.readFileSync(path.join(__dirname,'../js/yahoo-sync-v1.js'),'utf8');assert(!seasonSource.includes('window.localStorage'));assert(!syncSource.includes('window.localStorage'));});

async function repeatedSyncSizes(){const storage=memoryStorage(),profile={id:'repeat',season:2026,actualTeams:10,settings:{teams:10}},large=JSON.parse(JSON.stringify(fixture));large.players={players:Array.from({length:1400},(_,index)=>({playerKey:`461.p.${index+1}`,player_id:String(index+1),name:`Available Player ${index} ${'x'.repeat(50)}`,position:index%2?'WR':'RB',ownership:'W'}))};let counter=0;const transport={discover:async()=>({raw:large.league}),sync:async()=>{const value=JSON.parse(JSON.stringify(large));value.fetchedAt=`2026-10-${String((counter++%30)+1).padStart(2,'0')}T12:00:00.000Z`;return value;},status:async()=>({connected:true}),disconnect:async()=>({connected:false})},controller=Sync.createController({transport,storage,clock:()=>`2026-10-${String((counter%30)+1).padStart(2,'0')}T12:00:00.000Z`});controller.mapLeague(profile,{leagueKey:'461.l.10001',name:'Sanitized Test League',season:2026});const wanted=new Set([1,2,5,14,30]),sizes={};for(let index=1;index<=30;index++){await controller.sync({profile,canonicalPlayers:[],aliases:{},archives:[]});if(wanted.has(index))sizes[index]=storeSize(storage,controller.store.key(profile.id));}const state=controller.read(profile.id);assert.strictEqual(state.checkpoints.length,30);assert.strictEqual(state.snapshots,undefined);assert(sizes[30]<sizes[1]+100000);assert(sizes[30]<sizes[1]*1.35);return sizes;}
function storeSize(storage,key){return Buffer.byteLength(storage.getItem(key)||'','utf8');}

(async()=>{let passed=0,failures=[];for(const entry of tests){try{await entry.fn();passed++;}catch(error){failures.push({name:entry.name,error:error.stack||error.message});}}let sizes=null;try{sizes=await repeatedSyncSizes();passed++;}catch(error){failures.push({name:'30 repeated syncs remain bounded through the real controller path',error:error.stack||error.message});}console.log(JSON.stringify({passCount:passed,failCount:failures.length,failures,sizes,metrics}));if(failures.length)process.exit(1);})();
